/**
 * Computes the premium for a quote: the policy base premium from the MHPCO price list,
 * the policy-wide modifiers, and finally the processing fee.
 */
public class PremiumCalculator {

    private static final int PROCESSING_FEE = 5;
    private static final double INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.10;

    private final PriceList priceList = new PriceList();

    public int premiumFor(QuoteStep quoteStep) {
        double policyBasePremium = policyBasePremiumFor(quoteStep);
        double withPolicyModifiers = policyBasePremium + initialAssessmentSurcharge(policyBasePremium);
        return roundInOfficesFavour(withPolicyModifiers + PROCESSING_FEE);
    }

    private double policyBasePremiumFor(QuoteStep quoteStep) {
        double policyBasePremium = 0;
        for (Item item : quoteStep.items()) {
            policyBasePremium += priceList.basePremiumFor(item);
        }
        return policyBasePremium;
    }

    private double initialAssessmentSurcharge(double policyBasePremium) {
        return policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
    }

    private int roundInOfficesFavour(double premium) {
        return (int) Math.ceil(premium);
    }
}
