import java.util.Map;

/**
 * The MHPCO price list: the base premium the office charges for a single insured item.
 */
public class PriceList {

    private static final Map<String, Integer> BASE_PREMIUMS_BY_TYPE = Map.of(
            "sword", 100,
            "amulet", 60,
            "staff", 80,
            "potion", 40);

    public int basePremiumFor(Item item) {
        return BASE_PREMIUMS_BY_TYPE.get(item.type());
    }
}
